					"desc": "降低水产饲料在原料收集、加工、使用过程中的温室气体排放，包括：(1) 在饲料原料收集、处理以及饲料加工过程中使用光伏、风能、生物质能等新能源替代燃油等传统能源；选择本地饲料原料，减少运输产生的碳排放；改进生产工艺、设备和管理措施，提高生产效率；(2) 开发替代动物蛋白，使用 “碳 - 氮 - 磷” 平衡营养配方；使用发酵饲料等易消化吸收饲料，以及采用多菌种联合及益生元调控养殖动物肠道微生物菌群等技术；(3) 实施精准投喂，根据养殖品种的养殖特点和环境条件，制定投喂时间、投喂量、投喂频率等具体指标；根据养殖水质、温度、溶解氧等环境因素变化以及生长阶段、活动情况等及时调控投喂指标，减少饲料浪费。饲料利用率的计算标准参照《良好农业规范第 13 部分：水产养殖基础控制点与符合性规范》（GB/T 20014.13-2013）。"
