function getFieldsByIndustry(industry) {
	var data = catalogData[industry];
	if (!data || !data.fields) return [];
	return data.fields;
}

function getPathsByIndustryAndField(industry, field) {
	var data = catalogData[industry];
	if (!data) return [];
	if (field && data.domainPaths && data.domainPaths[field]) return data.domainPaths[field];
	if (!field && data.paths) return data.paths;
	return [];
}

function hasSubFields(industry) {
	return getFieldsByIndustry(industry).length > 0;
}

module.exports = {
	catalogData: catalogData,
	getFieldsByIndustry: getFieldsByIndustry,
	getPathsByIndustryAndField: getPathsByIndustryAndField,
	hasSubFields: hasSubFields
};
